import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class PublicExamplesTest{static void values(Object[]expected,Object[]actual){assertNotNull(actual);assertEquals(Arrays.stream(expected).map(TaskBinding::value).toList(),Arrays.stream(actual).map(TaskBinding::value).toList());}static Object[]select(Object[]input,java.util.function.Supplier<Object[]>call){Object[]refs=input.clone();var before=Arrays.stream(input).map(TaskBinding::value).toList();Object[]out=call.get();for(int i=0;i<input.length;i++)assertSame(refs[i],input[i]);assertEquals(before,Arrays.stream(input).map(TaskBinding::value).toList());return out;}@Test void exactDiagnosisOrderAndInclusiveRange(){Object a=TaskBinding.patient(1,1,"Flu"),b=TaskBinding.patient(2,2,"flu"),c=TaskBinding.patient(3,3,"Flu");Object[]in=TaskBinding.array(c,a,b,a);values(new Object[]{c,a,a},select(in,()->TaskBinding.diagnosis(in,"Flu")));values(new Object[]{a,b,a},select(in,()->TaskBinding.range(in,1,2)));}}
